const raw = $json.phone;

if (!raw || typeof raw !== 'string') {
  throw new Error('phone es obligatorio');
}

let value = raw.trim();

// Conservamos solo dígitos y un posible + inicial
value = value.replace(/[^\d+]/g, '');

// 0034XXXXXXXXX -> +34XXXXXXXXX
if (value.startsWith('0034')) {
  value = `+34${value.slice(4)}`;
}

// 34XXXXXXXXX -> +34XXXXXXXXX
else if (value.startsWith('34') && value.length === 11) {
  value = `+${value}`;
}

// XXXXXXXXX -> +34XXXXXXXXX
else if (/^\d{9}$/.test(value)) {
  value = `+34${value}`;
}

// +34XXXXXXXXX queda igual
else if (/^\+34\d{9}$/.test(value)) {
  // OK
}

else {
  throw new Error(`Formato de teléfono no soportado: ${raw}`);
}

return [
  {
    json: {
      phone_input: raw,
      phone_normalized: value
    }
  }
];

const rows = $json.data ?? [];

// Recuperamos la normalización realizada antes de consultar Directus.
// Así este workflow es la única fuente de verdad para normalizar teléfonos.
const normalized = $('Code · Normalize Phone').item.json;

const phoneInput = normalized.phone_input;
const phoneNormalized = normalized.phone_normalized;

if (!Array.isArray(rows)) {
  throw new Error('Respuesta inesperada de Directus');
}

if (!phoneNormalized) {
  throw new Error('phone_normalized no está disponible');
}

// ---------------------------------------------------------
// NOT FOUND
// ---------------------------------------------------------

if (rows.length === 0) {
  return [
    {
      json: {
        status: 'not_found',

        phone_input: phoneInput,
        phone_normalized: phoneNormalized,

        contact: null,
        phone: null,
        candidates: []
      }
    }
  ];
}

// ---------------------------------------------------------
// RESOLVED
// ---------------------------------------------------------

if (rows.length === 1) {
  const row = rows[0];

  if (!row.contact_id?.id) {
    throw new Error(
      'Directus devolvió un teléfono sin contacto válido'
    );
  }

  return [
    {
      json: {
        status: 'resolved',

        phone_input: phoneInput,
        phone_normalized: phoneNormalized,

        contact: row.contact_id,

        phone: {
          id: row.id,
          phone_number: row.phone_number,
          phone_normalized: row.phone_normalized,
          label: row.label,
          is_primary: row.is_primary,
          can_whatsapp: row.can_whatsapp
        },

        candidates: []
      }
    }
  ];
}

// ---------------------------------------------------------
// AMBIGUOUS
// ---------------------------------------------------------

return [
  {
    json: {
      status: 'ambiguous',

      phone_input: phoneInput,
      phone_normalized: phoneNormalized,

      contact: null,
      phone: null,

      candidates: rows.map((row) => ({
        contact: row.contact_id,

        phone: {
          id: row.id,
          phone_number: row.phone_number,
          phone_normalized: row.phone_normalized,
          label: row.label,
          is_primary: row.is_primary,
          can_whatsapp: row.can_whatsapp
        }
      }))
    }
  }
];
